const input = $input.first().json;
const event = input.body ?? input;
const token = input.headers?.['x-voicx-webhook-token'];
if (!token) throw new Error('Missing Voicx webhook authentication header');
return [{ json: { eventId: event.eventId, organizationId: event.organizationId, channel: event.channel, eventType: event.eventType, providerMessageId: event.providerMessageId, direction: event.direction, phone: event.phone, message: event.message, receivedAt: event.receivedAt } }];
